package com.adent.odontogram.api;
import com.adent.clinical.repository.ClinicalRecordRepository; import com.adent.odontogram.domain.*; import com.adent.odontogram.repository.*; import com.adent.patient.repository.PatientRepository; import com.adent.shared.exception.*; import com.adent.shared.security.CurrentUser; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.time.OffsetDateTime; import java.util.*;
@RestController @RequestMapping("/api/odontograms") @PreAuthorize("hasAnyRole('OWNER','DENTIST')")
public class OdontogramController {
 private final CurrentUser current;private final OdontogramRepository repo;private final OdontogramEntryRepository entries;private final PatientRepository patients;private final ClinicalRecordRepository records;
 public OdontogramController(CurrentUser c,OdontogramRepository r,OdontogramEntryRepository e,PatientRepository p,ClinicalRecordRepository cr){current=c;repo=r;entries=e;patients=p;records=cr;}
 @GetMapping("/patient/{patientId}") public List<Response> list(@PathVariable UUID patientId){patients.findByIdAndTenantId(patientId,current.tenantId()).orElseThrow(()->new NotFoundException("Paciente no encontrado"));return repo.findByTenantIdAndPatientIdOrderByVersionNoDesc(current.tenantId(),patientId).stream().map(this::response).toList();}
 @GetMapping("/{id}") public Response get(@PathVariable UUID id){return response(repo.findByIdAndTenantId(id,current.tenantId()).orElseThrow(()->new NotFoundException("Odontograma no encontrado")));}
 @PostMapping @PreAuthorize("hasRole('DENTIST')") @Transactional public Response create(@RequestBody Request r){UUID t=current.tenantId();patients.findByIdAndTenantId(r.patientId(),t).orElseThrow(()->new NotFoundException("Paciente no encontrado"));var cr=records.findByTenantIdAndPatientId(t,r.patientId()).orElseThrow(()->new BusinessException("Historia clínica no encontrada"));var previous=repo.findFirstByTenantIdAndPatientIdOrderByVersionNoDesc(t,r.patientId());int version=previous.map(x->x.getVersionNo()+1).orElse(1);previous.ifPresent(x->{x.setStatus("HISTORICAL");repo.save(x);});Odontogram o=new Odontogram();o.setTenantId(t);o.setClinicalRecordId(cr.getId());o.setPatientId(r.patientId());o.setEncounterId(r.encounterId());o.setVersionNo(version);o.setStatus(r.status()==null?"CURRENT":r.status());o.setDrawingJson(r.drawingJson()==null?"[]":r.drawingJson());o.setNotes(r.notes());o.setRecordedBy(current.username());o.setRecordedAt(OffsetDateTime.now());o=repo.save(o);if(r.entries()!=null)for(EntryRequest er:r.entries()){OdontogramEntry e=new OdontogramEntry();e.setTenantId(t);e.setOdontogramId(o.getId());e.setToothCode(er.toothCode());e.setSurfaceCode(er.surfaceCode());e.setConditionCode(er.conditionCode()==null?"NOTE":er.conditionCode());e.setDiagnosis(er.diagnosis());e.setTreatment(er.treatment());e.setEntryStatus(er.entryStatus());e.setColor(er.color());e.setNotes(er.notes());entries.save(e);}return response(o);}
 private Response response(Odontogram o){return new Response(o.getId(),o.getPatientId(),o.getEncounterId(),o.getVersionNo(),o.getStatus(),o.getRecordedAt(),o.getRecordedBy(),o.getDrawingJson(),o.getNotes(),entries.findByOdontogramIdOrderByToothCode(o.getId()));}
 public record EntryRequest(String toothCode,String surfaceCode,String conditionCode,String diagnosis,String treatment,String entryStatus,String color,String notes){} public record Request(UUID patientId,UUID encounterId,String status,String drawingJson,String notes,List<EntryRequest> entries){} public record Response(UUID id,UUID patientId,UUID encounterId,int versionNo,String status,OffsetDateTime recordedAt,String recordedBy,String drawingJson,String notes,List<OdontogramEntry> entries){}
}
